SELECT 
  (COUNT(*) FILTER (
       WHERE m.label = '+' 
         AND NOT EXISTS (
               SELECT 1 
               FROM atom a 
               WHERE a.molecule_id = m.molecule_id 
                 AND a.element = 'f'
           )
   )::numeric * 100) / NULLIF(
       COUNT(*) FILTER (WHERE m.label = '+'), 0
   ) AS percent_without_f
FROM molecule AS m;

SELECT MAX(consumption::float) AS max_monthly_consumption
FROM yearmonth
WHERE date LIKE '2012%';

WITH left_attrs AS (
    SELECT player_api_id, crossing
    FROM player_attributes
    WHERE preferred_foot = 'left'
), max_cross AS (
    SELECT MAX(crossing) AS max_crossing FROM left_attrs
)
SELECT COUNT(DISTINCT la.player_api_id) AS player_count
FROM left_attrs la, max_cross mc
WHERE la.crossing = mc.max_crossing;

SELECT 
    (SELECT COUNT(DISTINCT id) FROM laboratory WHERE plt < 100) AS lower_than_normal,
    (SELECT COUNT(DISTINCT id) FROM laboratory WHERE plt > 400) AS higher_than_normal;

SELECT DISTINCT type
FROM foreign_data
WHERE language = 'German';
